INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, alternatives, hint, explanation, topic, hr_slug, url, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'en', 'python', 'Divide and conquer', 'What does this code print?', 'print(7 // 2, 7 % 2)', NULL, '3 1', NULL, '`//` is integer division, `%` is the remainder.', '7 // 2 = 3 (integer division) and 7 % 2 = 1 (remainder).', 'operators', NULL, NULL, 'active', 'seed', 1767225600);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, alternatives, hint, explanation, topic, hr_slug, url, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'easy', 'fr', 'python', 'Diviser pour régner', 'Qu''affiche ce code ?', 'print(7 // 2, 7 % 2)', NULL, '3 1', NULL, '`//` est la division entière, `%` le reste.', '7 // 2 = 3 (division entière) et 7 % 2 = 1 (reste).', 'operators', NULL, NULL, 'active', 'seed', 1767225600);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, alternatives, hint, explanation, topic, hr_slug, url, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'easy', 'en', 'python', 'Index access', 'What is the time complexity of reading `my_list[i]` in Python?', NULL, '["O(1)", "O(log n)", "O(n)", "O(n log n)"]', 'A', NULL, 'A Python list is an array under the hood.', 'Lists are arrays: the address of element i is computed directly, so access is O(1).', 'complexity', NULL, NULL, 'active', 'seed', 1767225600);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, alternatives, hint, explanation, topic, hr_slug, url, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'easy', 'fr', 'python', 'Accès par indice', 'Quelle est la complexité de la lecture de `ma_liste[i]` en Python ?', NULL, '["O(1)", "O(log n)", "O(n)", "O(n log n)"]', 'A', NULL, 'Une liste Python est un tableau en interne.', 'Les listes sont des tableaux : l''adresse de l''élément i est calculée directement, l''accès est donc en O(1).', 'complexity', NULL, NULL, 'active', 'seed', 1767225600);
