INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, alternatives, hint, explanation, topic, hr_slug, url, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'medium', 'en', 'python', 'Fast lookup', 'Which built-in type gives O(1) average-time membership tests (`x in container`)?', NULL, '["list", "set", "tuple", "str"]', 'B', NULL, 'Think of hashing.', 'Sets are hash tables, so `x in my_set` is O(1) on average; lists, tuples and strings are scanned in O(n).', 'data structures', NULL, NULL, 'active', 'seed', 1767225600);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, alternatives, hint, explanation, topic, hr_slug, url, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'medium', 'fr', 'python', 'Recherche rapide', 'Quel type natif offre un test d''appartenance (`x in conteneur`) en O(1) en moyenne ?', NULL, '["list", "set", "tuple", "str"]', 'B', NULL, 'Pense au hachage.', 'Les ensembles (set) sont des tables de hachage : `x in mon_set` est en O(1) en moyenne ; les listes, tuples et chaînes sont parcourus en O(n).', 'data structures', NULL, NULL, 'active', 'seed', 1767225600);
